values ('M72601', 7, 'HSK 7–9 · HSK 3.0 загвар шалгалт №1 (全真模拟)', 91, 180, true, '[{"skill": "listening", "audio_url": "/mock-tests/m72601/listening.mp3", "time_min": 30, "parts": [{"part": 1, "range": [1, 10], "q_type": "judge", "desc": "Мэдээ — √/× шүүх"}, {"part": 2, "range": [11, 22], "q_type": "choice", "desc": "Яриа — сонгох / нөхөх"}, {"part": 3, "range": [23, 40], "q_type": "choice", "desc": "Лекц, өгүүлэл — сонгох / нөхөх"}]}, {"skill": "reading", "audio_url": null, "time_min": 60, "parts": [{"part": 1, "range": [41, 68], "q_type": "choice", "desc": "Эхэд тулгуурлан сонгох"}, {"part": 2, "range": [69, 73], "q_type": "choice", "desc": "Догол мөр эрэмбэлэх"}, {"part": 3, "range": [74, 87], "q_type": "essay", "desc": "Асуултад богино хариулах"}]}, {"skill": "writing", "audio_url": null, "time_min": 90, "parts": [{"part": 1, "range": [88, 88], "q_type": "essay_picture", "desc": "График тайлбарлах (15 мин)"}, {"part": 2, "range": [89, 89], "q_type": "essay", "desc": "Сэдэвт эсс (40 мин)"}, {"part": 3, "range": [90, 91], "q_type": "essay", "desc": "Орчуулга (35 мин)"}]}]'::jsonb, true)
