insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M72601','listening',1,1,'judge','所谓“车网互动”，是指新能源汽车与充电桩进行双向充放电。',null,'×','auto',1,'/mock-tests/m72601/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Мэдээнд «车网互动»-ийг «新能源汽车通过充电桩与电网进行双向充放电» гэж тодорхойлсон: машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээ (电网, diànwǎng)-тэй хоёр чиглэлд цэнэг солилцоно. Өгүүлбэр «与充电桩» гэж бичсэн нь буруу тул ×.',86.79,295.16,'近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。
2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。
“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。
据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。','{"transcript": [{"zh": "近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。", "mn": "Саяхан Цзянсу мужийн Үүшиэ хотод «тээврийн хэрэгсэл ба цахилгаан сүлжээний харилцан үйлчлэл»-ийн үзүүлэнгийн бүс албан ёсоор арилжааны горимд орлоо. «Тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэл» гэдэг нь шинэ эрчим хүчний машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээтэй хоёр чиглэлд цэнэглэх, цэнэг буцааж өгөх үйлдлийг хэлнэ. Уламжлалт нэг чиглэлтэй урсгал өөрчлөгдөж, шинэ эрчим хүчний машин сүлжээний зөөврийн «цэнэглэгч батарей» болжээ. Одоогийн байдлаар 1200 гаруй машин буцаан цэнэг өгөхөд оролцож, нийт буцаасан цахилгаан 24 мянган киловатт цагаас давлаа."}, {"zh": "2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。", "mn": "2023 оны 12-р сард Үндэсний хөгжил, шинэчлэлийн хороо, Үндэсний эрчим хүчний алба, Үйлдвэр, мэдээллийн технологийн яам зэрэг байгууллага хамтран «Шинэ эрчим хүчний машин ба цахилгаан сүлжээний нэгдмэл харилцан үйлчлэлийг эрчимжүүлэх тухай хэрэгжүүлэх санал»-ыг гаргаж, Урт мөрний бэлчир, Сувдан мөрний бэлчир, Бээжин-Тяньцзинь-Хэбэй-Шаньдун, Сычуань-Чунцин зэрэг нөхцөл нь харьцангуй боловсорсон бүс нутагт өргөн цар хүрээтэй туршилт, үзүүлэн хийхээр тусгаж, 2025 оны эцэс гэхэд 5-аас дээш үзүүлэнгийн хот, 50-аас дээш хоёр чиглэлтэй цэнэглэх-цэнэг буцаах үзүүлэнгийн төсөл байгуулахыг зорьсон."}, {"zh": "“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。", "mn": "«Шинэ эрчим хүчний машин цэнэглэх, цэнэг буцаах төхөөрөмжөөр дамжуулан нийтийн цахилгаан сүлжээ, бичил сүлжээ зэрэг хангамжийн систем, эсвэл барилга, орон сууцны хуваарилах системтэй холбогдож, хөдөлгүүрийн батарейг зөөврийн эрчим хүч хадгалах станц болгон сүлжээний ажиллагаанд оролцуулж, цахилгаан машин ба сүлжээний хооронд эрчим хүчний урсгал, мэдээллийн урсгалын хоёр талын харилцан үйлчлэлийг хэрэгжүүлдэг» гэж Үүшиэ цахилгаан машины үйлчилгээний компанийн дарга Се Жаожүнь хэлэв."}, {"zh": "据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。", "mn": "Танилцуулсанаар, жил бүр цахилгаан хэрэглээний оргил улиралд олон хот цахилгаан дутагдал, хангамжийн хурцадмал байдалтай тулгарсаар байгаа бөгөөд цахилгааныг бүс нутаг дамжуулан хуваарилах шаардлага байнга гардаг. Шинэ эрчим хүчний машин нь чанартай эрчим хүч хадгалах сав шиг тул нэгдсэн төлөвлөлтөөр сүлжээнд холбож чадвал ирээдүй өргөн."}], "key": "新能源汽车通过充电桩与电网进行双向充放电", "keyMn": "Шинэ эрчим хүчний машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээтэй хоёр чиглэлд цэнэг солилцоно", "trap": "Өгүүлбэр нь «电网» гэсэн гол үгийг «充电桩»-ээр сольсон.", "tip": "Тодорхойлолтын өгүүлбэрт гол объект (хэнтэй/юутай) таардаг эсэхийг шалга.", "words": [{"zh": "车网互动", "pinyin": "chē wǎng hùdòng", "mn": "машин-сүлжээний харилцан үйлчлэл"}, {"zh": "充电桩", "pinyin": "chōngdiànzhuāng", "mn": "цэнэглэх цэг"}, {"zh": "电网", "pinyin": "diànwǎng", "mn": "цахилгаан сүлжээ"}, {"zh": "双向", "pinyin": "shuāngxiàng", "mn": "хоёр чиглэлтэй"}], "why": "Мэдээнд «车网互动»-ийг «新能源汽车通过充电桩与电网进行双向充放电» гэж тодорхойлсон: машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээ (电网, diànwǎng)-тэй хоёр чиглэлд цэнэг солилцоно. Өгүүлбэр «与充电桩» гэж бичсэн нь буруу тул ×."}'::jsonb),
('M72601','listening',1,2,'judge','截至目前，新能源汽车参与反向放电的累计放电量超过2.4万千瓦时。',null,'√','auto',1,'/mock-tests/m72601/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эхний догол мөрийн төгсгөлд «已有超过1200辆…参与反向放电，累计放电量超过2.4万千瓦时» гэсэн тул хэллэг яг таарна. √.',86.79,295.16,'近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。
2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。
“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。
据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。','{"transcript": [{"zh": "近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。", "mn": "Саяхан Цзянсу мужийн Үүшиэ хотод «тээврийн хэрэгсэл ба цахилгаан сүлжээний харилцан үйлчлэл»-ийн үзүүлэнгийн бүс албан ёсоор арилжааны горимд орлоо. «Тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэл» гэдэг нь шинэ эрчим хүчний машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээтэй хоёр чиглэлд цэнэглэх, цэнэг буцааж өгөх үйлдлийг хэлнэ. Уламжлалт нэг чиглэлтэй урсгал өөрчлөгдөж, шинэ эрчим хүчний машин сүлжээний зөөврийн «цэнэглэгч батарей» болжээ. Одоогийн байдлаар 1200 гаруй машин буцаан цэнэг өгөхөд оролцож, нийт буцаасан цахилгаан 24 мянган киловатт цагаас давлаа."}, {"zh": "2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。", "mn": "2023 оны 12-р сард Үндэсний хөгжил, шинэчлэлийн хороо, Үндэсний эрчим хүчний алба, Үйлдвэр, мэдээллийн технологийн яам зэрэг байгууллага хамтран «Шинэ эрчим хүчний машин ба цахилгаан сүлжээний нэгдмэл харилцан үйлчлэлийг эрчимжүүлэх тухай хэрэгжүүлэх санал»-ыг гаргаж, Урт мөрний бэлчир, Сувдан мөрний бэлчир, Бээжин-Тяньцзинь-Хэбэй-Шаньдун, Сычуань-Чунцин зэрэг нөхцөл нь харьцангуй боловсорсон бүс нутагт өргөн цар хүрээтэй туршилт, үзүүлэн хийхээр тусгаж, 2025 оны эцэс гэхэд 5-аас дээш үзүүлэнгийн хот, 50-аас дээш хоёр чиглэлтэй цэнэглэх-цэнэг буцаах үзүүлэнгийн төсөл байгуулахыг зорьсон."}, {"zh": "“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。", "mn": "«Шинэ эрчим хүчний машин цэнэглэх, цэнэг буцаах төхөөрөмжөөр дамжуулан нийтийн цахилгаан сүлжээ, бичил сүлжээ зэрэг хангамжийн систем, эсвэл барилга, орон сууцны хуваарилах системтэй холбогдож, хөдөлгүүрийн батарейг зөөврийн эрчим хүч хадгалах станц болгон сүлжээний ажиллагаанд оролцуулж, цахилгаан машин ба сүлжээний хооронд эрчим хүчний урсгал, мэдээллийн урсгалын хоёр талын харилцан үйлчлэлийг хэрэгжүүлдэг» гэж Үүшиэ цахилгаан машины үйлчилгээний компанийн дарга Се Жаожүнь хэлэв."}, {"zh": "据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。", "mn": "Танилцуулсанаар, жил бүр цахилгаан хэрэглээний оргил улиралд олон хот цахилгаан дутагдал, хангамжийн хурцадмал байдалтай тулгарсаар байгаа бөгөөд цахилгааныг бүс нутаг дамжуулан хуваарилах шаардлага байнга гардаг. Шинэ эрчим хүчний машин нь чанартай эрчим хүч хадгалах сав шиг тул нэгдсэн төлөвлөлтөөр сүлжээнд холбож чадвал ирээдүй өргөн."}], "key": "累计放电量超过2.4万千瓦时", "keyMn": "Нийт буцаасан цахилгаан 24 мянган кВт цагаас давсан", "tip": "Тоо, хэмжээний асуултад мэдээний тоотой шууд тулга.", "words": [{"zh": "累计", "pinyin": "lěijì", "mn": "нийт, хуримтлагдсан"}, {"zh": "放电", "pinyin": "fàngdiàn", "mn": "цэнэг буцааж өгөх"}, {"zh": "千瓦时", "pinyin": "qiānwǎshí", "mn": "киловатт цаг"}], "why": "Эхний догол мөрийн төгсгөлд «已有超过1200辆…参与反向放电，累计放电量超过2.4万千瓦时» гэсэн тул хэллэг яг таарна. √."}'::jsonb),
('M72601','listening',1,3,'judge','新能源汽车将动力电池作为移动储能电站参与电网运行，有利于实现电动汽车与电网间的能量流、信息流双向互动。',null,'√','auto',1,'/mock-tests/m72601/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Се Жаожүнь «将动力电池作为移动储能电站参与电网运行，实现…能量流、信息流双向互动» гэж хэлсэн. Энэ нь тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэлийн ашиг тус тул √.',86.79,295.16,'近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。
2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。
“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。
据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。','{"transcript": [{"zh": "近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。", "mn": "Саяхан Цзянсу мужийн Үүшиэ хотод «тээврийн хэрэгсэл ба цахилгаан сүлжээний харилцан үйлчлэл»-ийн үзүүлэнгийн бүс албан ёсоор арилжааны горимд орлоо. «Тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэл» гэдэг нь шинэ эрчим хүчний машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээтэй хоёр чиглэлд цэнэглэх, цэнэг буцааж өгөх үйлдлийг хэлнэ. Уламжлалт нэг чиглэлтэй урсгал өөрчлөгдөж, шинэ эрчим хүчний машин сүлжээний зөөврийн «цэнэглэгч батарей» болжээ. Одоогийн байдлаар 1200 гаруй машин буцаан цэнэг өгөхөд оролцож, нийт буцаасан цахилгаан 24 мянган киловатт цагаас давлаа."}, {"zh": "2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。", "mn": "2023 оны 12-р сард Үндэсний хөгжил, шинэчлэлийн хороо, Үндэсний эрчим хүчний алба, Үйлдвэр, мэдээллийн технологийн яам зэрэг байгууллага хамтран «Шинэ эрчим хүчний машин ба цахилгаан сүлжээний нэгдмэл харилцан үйлчлэлийг эрчимжүүлэх тухай хэрэгжүүлэх санал»-ыг гаргаж, Урт мөрний бэлчир, Сувдан мөрний бэлчир, Бээжин-Тяньцзинь-Хэбэй-Шаньдун, Сычуань-Чунцин зэрэг нөхцөл нь харьцангуй боловсорсон бүс нутагт өргөн цар хүрээтэй туршилт, үзүүлэн хийхээр тусгаж, 2025 оны эцэс гэхэд 5-аас дээш үзүүлэнгийн хот, 50-аас дээш хоёр чиглэлтэй цэнэглэх-цэнэг буцаах үзүүлэнгийн төсөл байгуулахыг зорьсон."}, {"zh": "“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。", "mn": "«Шинэ эрчим хүчний машин цэнэглэх, цэнэг буцаах төхөөрөмжөөр дамжуулан нийтийн цахилгаан сүлжээ, бичил сүлжээ зэрэг хангамжийн систем, эсвэл барилга, орон сууцны хуваарилах системтэй холбогдож, хөдөлгүүрийн батарейг зөөврийн эрчим хүч хадгалах станц болгон сүлжээний ажиллагаанд оролцуулж, цахилгаан машин ба сүлжээний хооронд эрчим хүчний урсгал, мэдээллийн урсгалын хоёр талын харилцан үйлчлэлийг хэрэгжүүлдэг» гэж Үүшиэ цахилгаан машины үйлчилгээний компанийн дарга Се Жаожүнь хэлэв."}, {"zh": "据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。", "mn": "Танилцуулсанаар, жил бүр цахилгаан хэрэглээний оргил улиралд олон хот цахилгаан дутагдал, хангамжийн хурцадмал байдалтай тулгарсаар байгаа бөгөөд цахилгааныг бүс нутаг дамжуулан хуваарилах шаардлага байнга гардаг. Шинэ эрчим хүчний машин нь чанартай эрчим хүч хадгалах сав шиг тул нэгдсэн төлөвлөлтөөр сүлжээнд холбож чадвал ирээдүй өргөн."}], "key": "将动力电池作为移动储能电站参与电网运行", "keyMn": "Хөдөлгүүрийн батарейг зөөврийн эрчим хүч хадгалах станц болгон сүлжээнд оролцуулна", "words": [{"zh": "动力电池", "pinyin": "dònglì diànchí", "mn": "хөдөлгүүрийн батарей"}, {"zh": "储能", "pinyin": "chǔnéng", "mn": "эрчим хүч хадгалах"}, {"zh": "能量流", "pinyin": "néngliàngliú", "mn": "эрчим хүчний урсгал"}], "why": "Се Жаожүнь «将动力电池作为移动储能电站参与电网运行，实现…能量流、信息流双向互动» гэж хэлсэн. Энэ нь тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэлийн ашиг тус тул √."}'::jsonb),
('M72601','listening',1,4,'judge','新能源汽车相当于优质的储能容器，解决了不少城市面临的用电短缺、供电紧张的问题。',null,'×','auto',1,'/mock-tests/m72601/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Мэдээнд олон хот «仍然面临用电短缺、供电紧张» гэсэн, шинэ эрчим хүчний машин нь «相当于优质的储能容器» бөгөөд зохицуулж чадвал «前景广阔» гэсэн. Бүр шийдсэн гэсэнгүй тул ×.',86.79,295.16,'近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。
2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。
“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。
据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。','{"transcript": [{"zh": "近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。", "mn": "Саяхан Цзянсу мужийн Үүшиэ хотод «тээврийн хэрэгсэл ба цахилгаан сүлжээний харилцан үйлчлэл»-ийн үзүүлэнгийн бүс албан ёсоор арилжааны горимд орлоо. «Тээврийн хэрэгсэл ба сүлжээний харилцан үйлчлэл» гэдэг нь шинэ эрчим хүчний машин цэнэглэх цэгээр дамжуулан цахилгаан сүлжээтэй хоёр чиглэлд цэнэглэх, цэнэг буцааж өгөх үйлдлийг хэлнэ. Уламжлалт нэг чиглэлтэй урсгал өөрчлөгдөж, шинэ эрчим хүчний машин сүлжээний зөөврийн «цэнэглэгч батарей» болжээ. Одоогийн байдлаар 1200 гаруй машин буцаан цэнэг өгөхөд оролцож, нийт буцаасан цахилгаан 24 мянган киловатт цагаас давлаа."}, {"zh": "2023年12月，国家发展改革委、国家能源局、工业和信息化部等部门联合发布《关于加强新能源汽车与电网融合互动的实施意见》，提出初步在长三角、珠三角、京津冀鲁、川渝等条件相对成熟的地区开展车网互动规模化试点示范，力争2025年底前建成5个以上示范城市以及50个以上双向充放电示范项目。", "mn": "2023 оны 12-р сард Үндэсний хөгжил, шинэчлэлийн хороо, Үндэсний эрчим хүчний алба, Үйлдвэр, мэдээллийн технологийн яам зэрэг байгууллага хамтран «Шинэ эрчим хүчний машин ба цахилгаан сүлжээний нэгдмэл харилцан үйлчлэлийг эрчимжүүлэх тухай хэрэгжүүлэх санал»-ыг гаргаж, Урт мөрний бэлчир, Сувдан мөрний бэлчир, Бээжин-Тяньцзинь-Хэбэй-Шаньдун, Сычуань-Чунцин зэрэг нөхцөл нь харьцангуй боловсорсон бүс нутагт өргөн цар хүрээтэй туршилт, үзүүлэн хийхээр тусгаж, 2025 оны эцэс гэхэд 5-аас дээш үзүүлэнгийн хот, 50-аас дээш хоёр чиглэлтэй цэнэглэх-цэнэг буцаах үзүүлэнгийн төсөл байгуулахыг зорьсон."}, {"zh": "“新能源汽车通过充放电装置，与公共电网、微电网等供电系统或楼宇、住宅等配电系统相连，将动力电池作为移动储能电站参与电网运行，实现电动汽车与电网间的能量流、信息流双向互动。”国网无锡电动汽车服务有限公司董事长谢照军说。", "mn": "«Шинэ эрчим хүчний машин цэнэглэх, цэнэг буцаах төхөөрөмжөөр дамжуулан нийтийн цахилгаан сүлжээ, бичил сүлжээ зэрэг хангамжийн систем, эсвэл барилга, орон сууцны хуваарилах системтэй холбогдож, хөдөлгүүрийн батарейг зөөврийн эрчим хүч хадгалах станц болгон сүлжээний ажиллагаанд оролцуулж, цахилгаан машин ба сүлжээний хооронд эрчим хүчний урсгал, мэдээллийн урсгалын хоёр талын харилцан үйлчлэлийг хэрэгжүүлдэг» гэж Үүшиэ цахилгаан машины үйлчилгээний компанийн дарга Се Жаожүнь хэлэв."}, {"zh": "据介绍，在每年用电高峰季节，不少城市仍然面临用电短缺、供电紧张的问题，经常需要对电力资源进行跨区域调度。新能源汽车相当于优质的储能容器，如果能够统筹并网调度，前景广阔。", "mn": "Танилцуулсанаар, жил бүр цахилгаан хэрэглээний оргил улиралд олон хот цахилгаан дутагдал, хангамжийн хурцадмал байдалтай тулгарсаар байгаа бөгөөд цахилгааныг бүс нутаг дамжуулан хуваарилах шаардлага байнга гардаг. Шинэ эрчим хүчний машин нь чанартай эрчим хүч хадгалах сав шиг тул нэгдсэн төлөвлөлтөөр сүлжээнд холбож чадвал ирээдүй өргөн."}], "key": "如果能够统筹并网调度，前景广阔", "keyMn": "Хэрэв нэгдсэн төлөвлөлтөөр сүлжээнд холбож чадвал ирээдүй өргөн", "trap": "«相当于…» (адил) ба «解决了» (шийдсэн) өөр.", "tip": "«Шийдсэн» гэх мэт хэт тодорхой дүгнэлтийг сэжиглэ.", "words": [{"zh": "用电短缺", "pinyin": "yòngdiàn duǎnquē", "mn": "цахилгаан дутагдал"}, {"zh": "统筹", "pinyin": "tǒngchóu", "mn": "нэгдсэн төлөвлөх"}, {"zh": "前景广阔", "pinyin": "qiánjǐng guǎngkuò", "mn": "ирээдүй өргөн"}], "why": "Мэдээнд олон хот «仍然面临用电短缺、供电紧张» гэсэн, шинэ эрчим хүчний машин нь «相当于优质的储能容器» бөгөөд зохицуулж чадвал «前景广阔» гэсэн. Бүр шийдсэн гэсэнгүй тул ×."}'::jsonb),
('M72601','listening',1,5,'judge','这则新闻主要谈的是新能源汽车与电网融合互动前景广阔。',null,'√','auto',1,'/mock-tests/m72601/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Мэдээ нь туршилтын бүс, бодлого, батарейг эрчим хүч хадгалах болгон ашиглах тухай өгүүлж, төгсгөлд нь «前景广阔» гэж дүгнэсэн. Гол санаа нь харилцан үйлчлэлийн өргөн ирээдүй тул √.',86.79,295.16,'近日，江苏无锡车网互动示范区正式商用。所谓“车网互动”，是指新能源汽车通过充电桩与电网进行双向充放电。传统的单一流向被改变，新能源汽车变成了电网的移动“充电宝”。截至目前，已有超过1200辆新能源汽车参与反向放电，累计放电量超过2.4万千瓦时。
