★ 黄河水为什么黄？','[{"key": "A", "text": "源头水质不好"}, {"key": "B", "text": "支流汇入泥沙"}, {"key": "C", "text": "沿岸排放污物"}, {"key": "D", "text": "自然灾害导致"}]'::jsonb,'B','auto',1,null,null,false,array['sk.reading.choice','voc.hsk6','hsk30']::text[],'4-р догол мөр: «真正让黄河变“黄”的原因主要还是一条条…裹泥带沙的支流汇入». B.',null,null,null,'{"key": "支流汇入", "keyMn": "Цутгалууд шороо шавар авчирч цутгадаг", "wrong": {"A": "Эх нь «清澈见底» (тунгалаг).", "C": "Бохирдол гэж хэлээгүй.", "D": "Гамшиг шалтгаан биш."}, "words": [{"zh": "浑浊", "pinyin": "húnzhuó", "mn": "булингар"}, {"zh": "裹泥带沙", "pinyin": "guǒ ní dài shā", "mn": "шавар элс авчрах"}, {"zh": "水土流失", "pinyin": "shuǐtǔ liúshī", "mn": "хөрсний элэгдэл"}], "why": "4-р догол мөр: «真正让黄河变“黄”的原因主要还是一条条…裹泥带沙的支流汇入». B."}'::jsonb),
